#include "Theme.h"

#include "EmbeddedFonts.h" // generated by CMake

namespace ironclip::ui
{

void LoadFonts(IGraphics& g)
{
  using namespace ironclip::resources;
  g.LoadFont(font::kMedium, const_cast<unsigned char*>(kFontMedium), kFontMediumSize);
  g.LoadFont(font::kSemiBold, const_cast<unsigned char*>(kFontSemiBold), kFontSemiBoldSize);
  g.LoadFont(font::kBold, const_cast<unsigned char*>(kFontBold), kFontBoldSize);
}

namespace
{

/** Length in bytes of the UTF-8 sequence starting with `lead`. */
int Utf8Length(unsigned char lead)
{
  if (lead < 0x80)
    return 1;
  if ((lead >> 5) == 0x6)
    return 2;
  if ((lead >> 4) == 0xE)
    return 3;
  if ((lead >> 3) == 0x1E)
    return 4;
  return 1; // invalid lead byte: treat as a single unit
}

/** Calls fn(glyph) for every code point of str as a NUL-terminated string. */
template <typename Fn>
void ForEachGlyph(const char* str, Fn&& fn)
{
  char glyph[5];
  for (const char* c = str; *c;)
  {
    int len = Utf8Length(static_cast<unsigned char>(*c));
    int i = 0;
    for (; i < len && c[i]; ++i)
      glyph[i] = c[i];
    glyph[i] = 0;
    fn(glyph);
    c += i;
  }
}

} // namespace

float MeasureTracked(IGraphics& g, const IText& text, const char* str, float tracking)
{
  float width = 0.f;
  int count = 0;
  ForEachGlyph(str, [&](const char* glyph) {
    IRECT r;
    width += g.MeasureText(text, glyph, r);
    ++count;
  });
  return count > 1 ? width + tracking * static_cast<float>(count - 1) : width;
}

void DrawTracked(IGraphics& g, const IText& text, const char* str, const IRECT& bounds, float tracking)
{
  const float total = MeasureTracked(g, text, str, tracking);
  float x = bounds.L;
  if (text.mAlign == EAlign::Center)
    x = bounds.MW() - total * 0.5f;
  else if (text.mAlign == EAlign::Far)
    x = bounds.R - total;

  IText left = text;
  left.mAlign = EAlign::Near;
  ForEachGlyph(str, [&](const char* glyph) {
    IRECT r;
    const float w = g.MeasureText(left, glyph, r);
    g.DrawText(left, glyph, IRECT(x, bounds.T, x + w + 1.f, bounds.B));
    x += w + tracking;
  });
}

} // namespace ironclip::ui
